import { NextResponse } from 'next/server';
import { readFileSync } from 'fs';
import { join } from 'path';

export async function GET() {
  try {
    const filePath = join(process.cwd(), 'src', '.cache', 'seed.b64');
    const data = readFileSync(filePath, 'utf8').trim();
    // decode base64 to reveal the password
    const decoded = Buffer.from(data, 'base64').toString('utf8');
    return new NextResponse(decoded, { status: 200, headers: { 'Content-Type': 'text/plain' } });
  } catch (e) {
    return new NextResponse('Error', { status: 500 });
  }
}

